// Calcula as datas a partir de "agora", para a collection nunca ficar com datas vencidas.
// Os horários são enviados no fuso local de quem executa (ex.: -03:00).
const pad = (n) => String(n).padStart(2, '0');
const offset = (date) => {
  const minutes = -date.getTimezoneOffset();
  const sign = minutes >= 0 ? '+' : '-';
  const abs = Math.abs(minutes);
  return `${sign}${pad(Math.floor(abs / 60))}:${pad(abs % 60)}`;
};
const iso = (day, hour, minute) => {
  const d = new Date(day);
  d.setHours(hour, minute, 0, 0);
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(hour)}:${pad(minute)}:00${offset(d)}`;
};
const isWeekday = (d) => d.getDay() !== 0 && d.getDay() !== 6;
const nextWeekday = (from) => {
  const d = new Date(from);
  do { d.setDate(d.getDate() + 1); } while (!isWeekday(d));
  return d;
};

const now = new Date();
// Pelo menos 2 dias à frente, para também permitir o cancelamento (24h).
const tomorrow = new Date(now);
tomorrow.setDate(tomorrow.getDate() + 1);
const dia1 = nextWeekday(tomorrow);
const dia2 = nextWeekday(dia1);
const dia3 = nextWeekday(dia2);
const sabado = new Date(now);
do { sabado.setDate(sabado.getDate() + 1); } while (sabado.getDay() !== 6);
const daqui1h = new Date(now.getTime() + 60 * 60 * 1000);
const daqui1h30 = new Date(now.getTime() + 90 * 60 * 1000);

const datas = {
  dia1_10h00: iso(dia1, 10, 0),
  dia1_10h30: iso(dia1, 10, 30),
  dia1_15h00: iso(dia1, 15, 0),
  dia1_15h30: iso(dia1, 15, 30),
  dia1_17h45: iso(dia1, 17, 45),
  dia1_18h15: iso(dia1, 18, 15),
  dia2_10h00: iso(dia2, 10, 0),
  dia2_10h30: iso(dia2, 10, 30),
  dia3_10h00: iso(dia3, 10, 0),
  dia3_10h30: iso(dia3, 10, 30),
  sabado_10h00: iso(sabado, 10, 0),
  sabado_10h30: iso(sabado, 10, 30),
  daqui_1h: iso(daqui1h, daqui1h.getHours(), daqui1h.getMinutes()),
  daqui_1h30: iso(daqui1h30, daqui1h30.getHours(), daqui1h30.getMinutes()),
};
Object.entries(datas).forEach(([chave, valor]) => insomnia.environment.set(chave, valor));

